package net.civeira.phylax.features.oauth.tokensecurity.application;

import java.util.List;
import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.features.oauth.tokensecurity.application.AcrPolicy.Level;

/**
 * ACR derived from the methods actually used (tasks 1.13 and 3.10).
 */
class AcrPolicyUnitTest {

  private final AcrPolicy policy = new AcrPolicy("urn:x:1fa, legacy-1", "urn:x:mfa,legacy-2");

  @Test
  @DisplayName("The level follows amr: mfa is multi factor, anything else single factor")
  void level_from_amr() {
    Assertions.assertEquals("urn:x:mfa", policy.acr(List.of("pwd", "otp", "mfa")));
    Assertions.assertEquals("urn:x:1fa", policy.acr(List.of("pwd")));
    Assertions.assertEquals("urn:x:1fa", policy.acr(List.of()));
    Assertions.assertEquals(List.of("urn:x:1fa", "urn:x:mfa"), policy.supported());
  }

  @Test
  @DisplayName("acr_values: the first known value wins, aliases count, unknown ones are ignored")
  void requested_level() {
    Assertions.assertEquals(Optional.of(Level.MULTI_FACTOR),
        policy.requested("unknown legacy-2 urn:x:1fa"));
    Assertions.assertEquals(Optional.empty(), policy.requested("2 unknown"));
    Assertions.assertEquals(Optional.empty(), policy.requested(null));
  }

  @Test
  @DisplayName("A value cannot name both levels")
  void levels_must_not_overlap() {
    Assertions.assertThrows(IllegalArgumentException.class, () -> new AcrPolicy("a,b", "b"));
  }
}
